package com.payguard.base; import org.openqa.selenium.WebDriver; import org.openqa.selenium.chrome.ChromeDriver; import org.openqa.selenium.chrome.ChromeOptions; import org.testng.annotations.AfterMethod; import org.testng.annotations.BeforeMethod; import java.time.Duration; public class BaseTest { private static final ThreadLocal<WebDriver> driverThread = new ThreadLocal<>(); @BeforeMethod(alwaysRun = true) public void setUp() { if (driverThread.get() == null) { ChromeOptions options = new ChromeOptions(); if (Boolean.parseBoolean(System.getProperty("headless", "true"))) { options.addArguments("--headless=new"); } options.addArguments("--disable-gpu"); options.addArguments("--window-size=1920,1080"); options.addArguments("--no-sandbox"); options.addArguments("--disable-dev-shm-usage"); WebDriver driver = new ChromeDriver(options); driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(10)); driverThread.set(driver); } } public static void setup() { if (driverThread.get() == null) { new BaseTest().setUp(); } } public static WebDriver getDriver() { if (driverThread.get() == null) { setup(); } return driverThread.get(); } @AfterMethod(alwaysRun = true) public void tearDown() { WebDriver driver = driverThread.get(); if (driver != null) { driver.quit(); driverThread.remove(); } } }
